:root {
  --bg: #10181a;
  --panel: rgba(16, 24, 26, 0.85);
  --panel-border: rgba(255, 255, 255, 0.1);
  --gold: #f3d96b;
  --green: #7bd690;
  --red: #ff5d6d;
  --blue: #67b9ff;
  --text: #f0f6ff;
  --muted: #b7c7d9;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: linear-gradient(180deg, #0d1718 0%, #1d2a25 100%);
  color: var(--text);
  font-family: Arial, Helvetica, sans-serif;
}

body {
  display: grid;
  place-items: center;
}

#game-shell {
  position: relative;
  width: min(100vw, 1280px);
  height: min(100vh, 720px);
  border: 2px solid rgba(255,255,255,0.08);
  background: #111;
  overflow: hidden;
  box-shadow: 0 25px 80px rgba(0, 0, 0, 0.5);
}

#gameCanvas {
  display: block;
  width: 100%;
  height: 100%;
  background: linear-gradient(180deg, #87d2ff 0%, #c8f0ff 55%, #d9f5c2 100%);
}

.overlay {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  background: rgba(5, 9, 14, 0.42);
  backdrop-filter: blur(2px);
}

.overlay.hidden,
.hud.hidden,
.message-box.hidden,
.touch-controls.hidden {
  display: none;
}

.panel {
  background: rgba(10, 17, 19, 0.86);
  border: 1px solid var(--panel-border);
  border-radius: 20px;
  box-shadow: 0 18px 50px rgba(0,0,0,0.35);
}

.intro-panel {
  width: min(90%, 540px);
  padding: 2.2rem 2rem;
}

.eyebrow {
  margin: 0 0 0.6rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--gold);
  font-size: 0.7rem;
}

h1, h2, h3, p {
  margin-top: 0;
}

h1 {
  font-size: clamp(2rem, 4vw, 3rem);
  margin-bottom: 1rem;
}

button {
  border: none;
  border-radius: 12px;
  background: linear-gradient(180deg, #75d2ff, #44a8ef);
  color: #062338;
  font-weight: 700;
  padding: 0.8rem 1.2rem;
  cursor: pointer;
  transition: transform 0.15s ease, filter 0.15s ease;
}

button:hover {
  filter: brightness(1.05);
  transform: translateY(-1px);
}

button:active {
  transform: translateY(1px);
}

.battle-panel {
  width: min(90%, 560px);
  padding: 1.2rem;
}

.battle-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
}

.enemy-hp-wrap {
  width: 180px;
}

.hp-bar {
  width: 100%;
  height: 12px;
  border-radius: 999px;
  overflow: hidden;
  background: rgba(255,255,255,0.12);
  border: 1px solid rgba(255,255,255,0.15);
}

.hp-fill {
  height: 100%;
  width: 100%;
  background: linear-gradient(90deg, #4ade80, #8ef0a5);
  transition: width 0.2s ease;
}

.battle-sprite-wrap {
  padding: 2rem 0 1rem;
  display: grid;
  place-items: center;
}

.battle-sprite {
  width: 160px;
  height: 160px;
  border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, rgba(255,255,255,0.9), rgba(234, 244, 255, 0.1) 35%, rgba(16,24,26,0.8) 36%), linear-gradient(135deg, #8fd16c, #6bb36f);
  border: 5px solid rgba(255,255,255,0.2);
  box-shadow: 0 25px 40px rgba(0,0,0,0.25);
  position: relative;
}

.battle-sprite::before,
.battle-sprite::after {
  content: "";
  position: absolute;
  inset: auto;
  background: rgba(28, 36, 42, 0.8);
}

.battle-sprite::before {
  width: 22px;
  height: 22px;
  left: 36px;
  top: 42px;
  border-radius: 50%;
}

.battle-sprite::after {
  width: 22px;
  height: 22px;
  right: 36px;
  top: 42px;
  border-radius: 50%;
}

.battle-log {
  min-height: 74px;
  background: rgba(11, 18, 22, 0.8);
  border-radius: 12px;
  padding: 0.85rem 1rem;
  color: var(--muted);
  line-height: 1.5;
  margin-bottom: 1rem;
}

.battle-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.75rem;
}

.hud {
  position: absolute;
  inset: 0;
  pointer-events: none;
  padding: 1rem;
}

.top-row,
.bottom-row {
  display: grid;
  grid-template-columns: repeat(3, minmax(140px, 1fr));
  gap: 1rem;
}

.bottom-row {
  margin-top: 1rem;
  grid-template-columns: 1.5fr 1fr;
}

.card {
  background: rgba(9, 17, 20, 0.72);
  border: 1px solid var(--panel-border);
  border-radius: 12px;
  padding: 0.85rem 1rem;
  backdrop-filter: blur(2px);
  pointer-events: auto;
}

.card h3 {
  margin-bottom: 0.5rem;
  font-size: 0.95rem;
  color: var(--gold);
}

.card p {
  margin-bottom: 0.3rem;
  font-size: 0.9rem;
}

.party-card {
  min-height: 100px;
}

#party-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.pokemon-tag {
  background: rgba(123, 214, 144, 0.18);
  border: 1px solid rgba(123, 214, 144, 0.35);
  border-radius: 999px;
  padding: 0.25rem 0.6rem;
  font-size: 0.8rem;
}

.bag-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.5rem;
}

.message-box {
  position: absolute;
  left: 50%;
  bottom: 20px;
  transform: translateX(-50%);
  min-width: min(72vw, 420px);
  text-align: center;
  padding: 0.8rem 1rem;
  border-radius: 12px;
  background: rgba(12, 20, 22, 0.9);
  border: 1px solid rgba(255,255,255,0.12);
  color: var(--text);
}

.touch-controls {
  position: absolute;
  inset: auto 0 0 0;
  display: flex;
  justify-content: space-between;
  align-items: end;
  padding: 1rem;
  pointer-events: none;
}

.dpad {
  display: grid;
  grid-template-columns: repeat(3, 52px);
  grid-template-rows: repeat(3, 52px);
  gap: 6px;
  pointer-events: auto;
}

.dpad button {
  width: 52px;
  height: 52px;
  padding: 0;
  display: grid;
  place-items: center;
  font-size: 1.4rem;
}

.dpad button:nth-child(1) { grid-column: 2; grid-row: 1; }
.dpad button:nth-child(2) { grid-column: 1; grid-row: 2; }
.dpad button:nth-child(3) { grid-column: 2; grid-row: 2; }
.dpad button:nth-child(4) { grid-column: 3; grid-row: 2; }

.action-button {
  pointer-events: auto;
  width: 118px;
  height: 52px;
  font-size: 1rem;
}

@media (max-width: 720px) {
  .top-row,
  .bottom-row {
    grid-template-columns: 1fr;
  }

  .hud {
    padding: 0.5rem;
  }

  .card {
    padding: 0.75rem 0.85rem;
  }
}

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

const startScreen = document.getElementById('start-screen');
const battleScreen = document.getElementById('battle-screen');
const hud = document.getElementById('hud');
const messageBox = document.getElementById('message-box');
const touchControls = document.getElementById('touch-controls');
const startBtn = document.getElementById('start-btn');
const questText = document.getElementById('quest-text');
const playerNameEl = document.getElementById('player-name');
const levelEl = document.getElementById('player-level');
const coinEl = document.getElementById('coin-count');
const onlineCountEl = document.getElementById('online-count');
const regionEl = document.getElementById('region-name');
const partyList = document.getElementById('party-list');
const ballCountEl = document.getElementById('ball-count');
const potionCountEl = document.getElementById('potion-count');
const enemyNameEl = document.getElementById('enemy-name');
const enemyHpFill = document.getElementById('enemy-hp-fill');
const battleLog = document.getElementById('battle-log');
const enemySprite = document.getElementById('enemy-sprite');

const WORLD_WIDTH = 2000;
const WORLD_HEIGHT = 1200;

const keys = new Set();
let lastTimestamp = 0;
let isGameStarted = false;
let activeScene = 'village';
let messageTimer = null;

const state = {
  player: {
    x: 350,
    y: 520,
    w: 28,
    h: 28,
    color: '#ffd76a',
    name: 'Astra',
    level: 1,
    coins: 0,
    balls: 4,
    potions: 3,
    facing: 'down'
  },
  playersOnline: 24,
  region: 'Brightwood',
  questIndex: 0,
  party: [
    { name: 'Piplup', type: 'water', level: 8 },
    { name: 'Pikachu', type: 'electric', level: 5 }
  ],
  worldObjects: [
    { type: 'house', x: 130, y: 180, w: 190, h: 130 },
    { type: 'house', x: 630, y: 180, w: 190, h: 130 },
    { type: 'tree', x: 880, y: 340, w: 80, h: 80 },
    { type: 'tree', x: 1010, y: 540, w: 80, h: 80 },
    { type: 'tree', x: 1220, y: 330, w: 80, h: 80 },
    { type: 'tree', x: 510, y: 760, w: 80, h: 80 },
    { type: 'sign', x: 330, y: 335, w: 44, h: 44 },
    { type: 'portal', x: 1500, y: 760, w: 60, h: 60 },
    { type: 'guide', x: 220, y: 430, w: 36, h: 36 }
  ],
  battle: null,
  wildCreatures: [
    { name: 'Pikachu', hp: 34, maxHp: 34, color: '#f7d652', type: 'electric' },
    { name: 'Bubblup', hp: 42, maxHp: 42, color: '#5cc2ff', type: 'water' },
    { name: 'Treecko', hp: 28, maxHp: 28, color: '#6bd57b', type: 'grass' },
    { name: 'Charmit', hp: 40, maxHp: 40, color: '#ffa076', type: 'fire' }
  ]
};

const quests = [
  'Talk to the town guide.',
  'Travel to the wild grass and catch a creature.',
  'Win a battle in the meadow.',
  'Return to the guide for your reward.'
];

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function showMessage(text) {
  messageBox.textContent = text;
  messageBox.classList.remove('hidden');
  clearTimeout(messageTimer);
  messageTimer = setTimeout(() => messageBox.classList.add('hidden'), 2400);
}

function updateHud() {
  playerNameEl.textContent = state.player.name;
  levelEl.textContent = state.player.level;
  coinEl.textContent = state.player.coins;
  onlineCountEl.textContent = state.playersOnline;
  regionEl.textContent = state.region;
  ballCountEl.textContent = state.player.balls;
  potionCountEl.textContent = state.player.potions;
  questText.textContent = quests[state.questIndex] || 'Quest complete!';

  partyList.innerHTML = '';
  state.party.forEach((member) => {
    const tag = document.createElement('span');
    tag.className = 'pokemon-tag';
    tag.textContent = `${member.name} Lv.${member.level}`;
    partyList.appendChild(tag);
  });
}

function startBattle(creature) {
  if (state.battle) return;
  const data = JSON.parse(JSON.stringify(creature));
  state.battle = {
    ...data,
    enemyName: data.name,
    log: `${data.name} appears! Choose an action.`
  };
  enemyNameEl.textContent = state.battle.name;
  enemyHpFill.style.width = `${(state.battle.hp / state.battle.maxHp) * 100}%`;
  battleLog.textContent = state.battle.log;
  battleScreen.classList.remove('hidden');
  enemySprite.style.background = `radial-gradient(circle at 30% 30%, rgba(255,255,255,0.9), rgba(234, 244, 255, 0.1) 35%, rgba(16,24,26,0.8) 36%), linear-gradient(135deg, ${creature.color}, #6bb36f)`;
}

function endBattle(success) {
  if (!state.battle) return;
  battleScreen.classList.add('hidden');
  const defeated = state.battle.name;
  state.battle = null;
  if (success) {
    state.player.coins += 10;
    state.questIndex = Math.min(state.questIndex + 1, quests.length - 1);
    showMessage(`${defeated} was defeated. +10 coins!`);
  }
  updateHud();
}

function doBattleAction(action) {
  if (!state.battle) return;

  const player = state.player;
  const enemy = state.battle;
  let log = '';

  switch (action) {
    case 'attack': {
      const damage = 8 + Math.floor(Math.random() * 6);
      enemy.hp = Math.max(0, enemy.hp - damage);
      log = `You strike ${enemy.name} for ${damage} damage.`;
      break;
    }
    case 'heal': {
      if (player.potions <= 0) {
        log = 'You have no potions left.';
        break;
      }
      player.potions -= 1;
      const heal = 12 + Math.floor(Math.random() * 7);
      log = `You use a potion and recover ${heal} health.`;
      break;
    }
    case 'capture': {
      if (player.balls <= 0) {
        log = 'You have no Pokéballs.';
        break;
      }
      player.balls -= 1;
      const chance = Math.random();
      if (chance > 0.58) {
        const caught = { name: enemy.name, type: enemy.type, level: 7 + Math.floor(Math.random() * 5) };
        state.party.push(caught);
        log = `${enemy.name} was captured!`;
        endBattle(true);
        updateHud();
        return;
      }
      log = `${enemy.name} broke free!`;
      break;
    }
    case 'run': {
      state.battle = null;
      battleScreen.classList.add('hidden');
      log = `You escaped from ${enemy.name}.`;
      break;
    }
    default:
      break;
  }

  if (enemy.hp > 0) {
    const enemyDamage = 5 + Math.floor(Math.random() * 7);
    log += ` ${enemy.name} attacks for ${enemyDamage}.`;
    state.player.level = Math.max(1, state.player.level + (Math.random() < 0.12 ? 1 : 0));
  } else {
    log += ` ${enemy.name} faints.`;
    endBattle(true);
  }

  battleLog.textContent = log;
  enemyHpFill.style.width = `${(enemy.hp / enemy.maxHp) * 100}%`;
  updateHud();
}

function isCollidingWithObject(x, y, obj) {
  return x + state.player.w > obj.x && x < obj.x + obj.w && y + state.player.h > obj.y && y < obj.y + obj.h;
}

function movePlayer(dx, dy) {
  if (!isGameStarted) return;
  const nextX = clamp(state.player.x + dx, 40, WORLD_WIDTH - 80);
  const nextY = clamp(state.player.y + dy, 40, WORLD_HEIGHT - 80);

  let blocked = false;
  for (const obj of state.worldObjects) {
    if (isCollidingWithObject(nextX, nextY, obj)) {
      blocked = true;
      break;
    }
  }

  if (!blocked) {
    state.player.x = nextX;
    state.player.y = nextY;
  }

  if (Math.abs(dx) > Math.abs(dy)) state.player.facing = dx < 0 ? 'left' : 'right';
  else if (dy !== 0) state.player.facing = dy < 0 ? 'up' : 'down';

  const targetWild = state.wildCreatures[Math.floor(Math.random() * state.wildCreatures.length)];
  const nearGrass = state.player.x > 900 && state.player.y > 250;
  if (nearGrass && Math.random() < 0.015) {
    startBattle(targetWild);
  }

  if (state.player.x > 1460 && state.player.y > 700 && state.questIndex === 2) {
    state.questIndex = 3;
    state.player.coins += 25;
    showMessage('Guild quest complete! +25 coins');
    updateHud();
  }
}

function interact() {
  const guideNear = Math.abs(state.player.x - 220) < 80 && Math.abs(state.player.y - 430) < 80;
  const signNear = Math.abs(state.player.x - 330) < 80 && Math.abs(state.player.y - 335) < 80;

  if (guideNear) {
    if (state.questIndex === 0) {
      state.questIndex = 1;
      showMessage('Guide: Head into the grass and catch a creature.');
    } else if (state.questIndex === 3) {
      state.questIndex = 3;
      showMessage('Guide: You did it! Welcome to Brightwood.');
    } else {
      showMessage('Guide: Keep exploring the wilds.');
    }
    updateHud();
    return;
  }

  if (signNear) {
    showMessage('Trail sign: Brightwood Meadow to the east.');
    return;
  }

  if (state.player.x > 900 && state.player.y > 250 && !state.battle) {
    const creature = state.wildCreatures[Math.floor(Math.random() * state.wildCreatures.length)];
    startBattle(creature);
  }
}

function update() {
  const moveSpeed = 4;
  if (keys.has('ArrowUp') || keys.has('w')) movePlayer(0, -moveSpeed);
  if (keys.has('ArrowDown') || keys.has('s')) movePlayer(0, moveSpeed);
  if (keys.has('ArrowLeft') || keys.has('a')) movePlayer(-moveSpeed, 0);
  if (keys.has('ArrowRight') || keys.has('d')) movePlayer(moveSpeed, 0);
}

function drawBackground() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  const sky = ctx.createLinearGradient(0, 0, 0, canvas.height);
  sky.addColorStop(0, '#7bd4ff');
  sky.addColorStop(0.6, '#d9f5ff');
  sky.addColorStop(1, '#d8f7c7');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = '#b9e38d';
  ctx.fillRect(0, 420, canvas.width, canvas.height - 420);

  ctx.fillStyle = '#5a804f';
  for (let i = 0; i < 18; i++) {
    const x = (i * 88) % canvas.width;
    const y = 420 + ((i * 57) % 120);
    ctx.fillRect(x, y, 50, 55);
  }

  ctx.fillStyle = '#a98d53';
  ctx.fillRect(80, 250, 220, 180);
  ctx.fillRect(620, 250, 220, 180);
  ctx.fillStyle = '#b1d0e9';
  ctx.fillRect(110, 280, 60, 50);
  ctx.fillRect(220, 280, 60, 50);
  ctx.fillRect(650, 280, 60, 50);
  ctx.fillRect(760, 280, 60, 50);

  ctx.fillStyle = '#6b8d5f';
  for (let i = 0; i < 10; i++) {
    const x = 900 + i * 95;
    const y = 300 + (i % 2) * 30;
    ctx.beginPath();
    ctx.arc(x, y, 30, 0, Math.PI * 2);
    ctx.fill();
  }

  ctx.fillStyle = '#7d4d37';
  ctx.fillRect(320, 300, 44, 60);
  ctx.fillStyle = '#f8e4a8';
  ctx.fillRect(330, 312, 24, 12);

  ctx.fillStyle = '#a0a0a0';
  ctx.fillRect(1450, 700, 80, 100);
  ctx.fillStyle = '#d7d7d7';
  ctx.fillRect(1470, 720, 40, 50);

  ctx.fillStyle = '#2b7a4a';
  ctx.fillRect(0, 610, canvas.width, 120);
}

function drawPlayer() {
  const { x, y, w, h, color, facing } = state.player;
  ctx.fillStyle = color;
  ctx.fillRect(x, y, w, h);

  ctx.fillStyle = '#1f2430';
  const eyeOffset = facing === 'left' ? -5 : 5;
  ctx.fillRect(x + 7 + eyeOffset, y + 6, 4, 4);
  ctx.fillRect(x + 17 + eyeOffset, y + 6, 4, 4);

  ctx.strokeStyle = '#4a3d2a';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(x + w / 2, y + h);
  ctx.lineTo(x + w / 2, y + h + 12);
  ctx.stroke();

  if (facing === 'left') {
    ctx.beginPath();
    ctx.moveTo(x, y + h / 2);
    ctx.lineTo(x - 8, y + h / 2 + 6);
    ctx.stroke();
  } else if (facing === 'right') {
    ctx.beginPath();
    ctx.moveTo(x + w, y + h / 2);
    ctx.lineTo(x + w + 8, y + h / 2 + 6);
    ctx.stroke();
  } else if (facing === 'up') {
    ctx.beginPath();
    ctx.moveTo(x + w / 2, y);
    ctx.lineTo(x + w / 2 - 6, y - 8);
    ctx.stroke();
  } else {
    ctx.beginPath();
    ctx.moveTo(x + w / 2, y + h);
    ctx.lineTo(x + w / 2 + 6, y + h + 8);
    ctx.stroke();
  }
}

function draw() {
  drawBackground();
  drawPlayer();
}

function tick(timestamp) {
  const delta = timestamp - lastTimestamp;
  if (delta > 0) {
    update();
    draw();
    lastTimestamp = timestamp;
  }
  requestAnimationFrame(tick);
}

function beginGame() {
  isGameStarted = true;
  startScreen.classList.add('hidden');
  hud.classList.remove('hidden');
  touchControls.classList.remove('hidden');
  updateHud();
  showMessage('Welcome to Brightwood!');
}

startBtn.addEventListener('click', beginGame);

document.addEventListener('keydown', (event) => {
  const key = event.key.length === 1 ? event.key.toLowerCase() : event.key;
  keys.add(key);

  if (key === 'e' || key === 'Enter') {
    interact();
  }

  if (key === ' ') {
    if (state.battle) {
      doBattleAction('attack');
    }
  }
});

document.addEventListener('keyup', (event) => {
  const key = event.key.length === 1 ? event.key.toLowerCase() : event.key;
  keys.delete(key);
});

document.querySelectorAll('[data-action]').forEach((button) => {
  button.addEventListener('click', () => {
    doBattleAction(button.dataset.action);
  });
});

document.querySelectorAll('[data-move]').forEach((button) => {
  button.addEventListener('click', () => {
    const direction = button.dataset.move;
    if (direction === 'up') movePlayer(0, -8);
    if (direction === 'down') movePlayer(0, 8);
    if (direction === 'left') movePlayer(-8, 0);
    if (direction === 'right') movePlayer(8, 0);
  });
});

document.getElementById('touch-action').addEventListener('click', interact);

updateHud();
requestAnimationFrame(tick);

