141: function doBattleAction(action) {
142:   if (!state.battle) return;
143: 
144:   const player = state.player;
145:   const enemy = state.battle;
146:   let log = '';
147: 
148:   switch (action) {
149:     case 'attack': {
150:       const damage = 8 + Math.floor(Math.random() * 6);
151:       enemy.hp = Math.max(0, enemy.hp - damage);
152:       log = `You strike ${enemy.name} for ${damage} damage.`;
153:       break;
154:     }
155:     case 'heal': {
156:       if (player.potions <= 0) {
157:         log = 'You have no potions left.';
158:         break;
159:       }
160:       player.potions -= 1;
161:       const heal = 12 + Math.floor(Math.random() * 7);
162:       log = `You use a potion and recover ${heal} health.`;
163:       break;
164:     }
165:     case 'capture': {
166:       if (player.balls <= 0) {
167:         log = 'You have no Pokéballs.';
168:         break;
169:       }
170:       player.balls -= 1;
171:       const chance = Math.random();
172:       if (chance > 0.58) {
173:         const caught = { name: enemy.name, type: enemy.type, level: 7 + Math.floor(Math.random() * 5) };
174:         state.party.push(caught);
175:         log = `${enemy.name} was captured!`;
176:         endBattle(true);
177:         updateHud();
178:         return;
179:       }
180:       log = `${enemy.name} broke free!`;
181:       break;
182:     }
183:     case 'run': {
184:       state.battle = null;
185:       battleScreen.classList.add('hidden');
186:       log = `You escaped from ${enemy.name}.`;
187:       break;
188:     }
189:     default:
190:       break;
191:   }
192: 
193:   if (enemy.hp > 0) {
194:     const enemyDamage = 5 + Math.floor(Math.random() * 7);
195:     log += ` ${enemy.name} attacks for ${enemyDamage}.`;
196:     state.player.level = Math.max(1, state.player.level + (Math.random() < 0.12 ? 1 : 0));
197:   } else {
198:     log += ` ${enemy.name} faints.`;
199:     endBattle(true);
